-- =============================================================================
-- ROLLBACK of the category split (parts 1 and 2).
-- GENERATED by scripts/gen-category-split-migration.mjs from src/lib/categorySplit.js.
-- Only the category of the "medical-bone-models" products changes. No product is
-- created, deleted, duplicated or edited otherwise (prices, names, photos,
-- stock, IDs, reviews and orders are untouched).
-- =============================================================================

-- Puts every moved product back exactly as it was (category, category_id,
-- extra categories) from public.category_split_backup_20261106, re-activates the old category and hides
-- Medical and Bones again (their rows are kept, nothing is deleted).
-- Then redeploy the previous website version.
begin;
update public.products p set
  category = b.category,
  category_id = b.category_id,
  extra_categories = b.extra_categories
from public.category_split_backup_20261106 b where b.product_id = p.id;
update public.categories set status = 'active' where slug = 'medical-bone-models';
update public.categories set status = 'inactive' where slug in ('medical', 'bones')
  and not exists (select 1 from public.products where category in ('medical', 'bones'));
commit;
